function failAlertCard(n,compact=false){const a=n.alert,items=a?.items||[],shown=compact?items.slice(0,3):items;const when=a?.when||fmtStamp(n.created_at);
 return `<article class="fail-alert${n.read_at?' is-read':''}"><div class="fail-alert-top"><span class="fail-alert-tag">Inspection alert</span>${n.read_at?'':'<span class="fail-alert-dot" aria-hidden="true"></span><span class="sr-only">Unread</span>'}<time>${esc(when)}</time></div><strong class="fail-alert-title">${a?esc(items.length+' failed item'+(items.length===1?'':'s')+' · '+a.property_name):esc(n.title)}</strong>${a?`<div class="fail-alert-meta">${esc(a.address||'Address not entered')}</div><div class="fail-alert-meta">Inspector: ${esc(a.inspector_name)}</div>`:''}${shown.length?`<ul class="fail-alert-items">${shown.map(i=>`<li><span class="fail-alert-item-label">${esc(i.label)}</span>${i.note?`<span class="fail-alert-note">${esc(i.note)}</span>`:'<span class="fail-alert-note is-empty">No note added</span>'}</li>`).join('')}</ul>`:''}${compact&&items.length>shown.length?`<div class="fail-alert-meta">and ${items.length-shown.length} more</div>`:''}<div class="fail-alert-actions">${btn('Open inspection','open-notification',n.id,true)}${n.read_at?'':btn('Mark read','read-notification',n.id)}</div></article>`;}
function notificationRow(n){return `<div class="row"><div><strong>${esc(n.title)}</strong><div class="muted">${esc(fmtStamp(n.created_at))}</div></div>${!n.read_at?btn('Mark read','read-notification',n.id):badge('read')}</div>`;}
function alertBell(){if(!isStaff())return '';const unread=(data.notifications||[]).filter(n=>!n.read_at),alerts=unread.filter(n=>n.kind==='inspection_fail'),others=unread.filter(n=>n.kind!=='inspection_fail');
 const label=`Notifications${unread.length?`, ${unread.length} unread`:''}${alerts.length?`, ${alerts.length} inspection alert${alerts.length===1?'':'s'}`:''}`;
 const panel=alertsOpen?`<div class="alert-panel" id="alertPanel" role="region" aria-label="Notifications"><div class="alert-panel-head"><strong>Notifications</strong>${unread.length?btn('Mark all read','read-all-notifications'):''}</div><div class="alert-panel-list">${alerts.map(n=>failAlertCard(n,true)).join('')}${others.slice(0,Math.max(0,6-alerts.length)).map(n=>`<div class="alert-panel-row"><div><strong>${esc(n.title)}</strong><div class="muted">${esc(fmtStamp(n.created_at))}</div></div>${btn('Mark read','read-notification',n.id)}</div>`).join('')}${unread.length?'':'<p class="alert-panel-empty">You are up to date.</p>'}</div><div class="alert-panel-foot">${btn('See all notifications','open-notifications-page')}</div></div>`:'';
 return `<div class="alert-bell-wrap"><button type="button" class="alert-bell${alerts.length?' has-alerts':''}" data-action="toggle-alerts" aria-expanded="${alertsOpen}" aria-label="${esc(label)}" title="Notifications">${bellIcon}${unread.length?`<span class="alert-bell-count">${unread.length>99?'99+':unread.length}</span>`:''}</button>${panel}</div>`;}
function sizeAlertPanel(){const panel=$('alertPanel');if(!panel)return;const room=window.innerHeight-panel.getBoundingClientRect().top-12;panel.style.maxHeight=Math.max(220,Math.min(window.innerWidth>760?560:room,room))+'px';}
function refreshBell(){const wrap=document.querySelector('.alert-bell-wrap');if(wrap)wrap.outerHTML=alertBell();sizeAlertPanel();}
function openLinkedInspection(){if(!pendingInspectionLink||!data)return;const target=pendingInspectionLink;pendingInspectionLink=null;try{const url=new URL(location.href);url.searchParams.delete('inspection');history.replaceState(history.state,'',url.pathname+url.search+url.hash);}catch{}if(isStaff()&&data.inspections.some(i=>i.id===target)){activeInspection=target;page='inspection';}}
