 if(page==='arrivals'){const pending=data.arrivals.filter(a=>!['ready','completed','cancelled'].includes(a.status)),ready=data.arrivals.filter(a=>['ready','completed'].includes(a.status));if(activeArrival){const a=data.arrivals.find(a=>a.id===activeArrival);if(a)return arrivalDetail(a);}const rows=arrivalFilter==='ready'?ready:pending;return head(forRole({staff:'Arrival preparation',client:'Arrivals'}),forRole({staff:'Upcoming owner arrivals: confirm the shopping, rooms and notes are ready.',client:'Tell us when you are coming and what to have ready.'}),btn('Plan arrival','new-arrival','',true))+`<div class="tabs"><button data-action="arrival-filter" data-id="pending" class="${arrivalFilter==='pending'?'active':''}">Needs confirmation (${pending.length})</button><button data-action="arrival-filter" data-id="ready" class="${arrivalFilter==='ready'?'active':''}">Ready (${ready.length})</button></div>`+arrivalCards(rows);}
