 if(tab==='inspections')html+=`<div class="panel">${isStaff()?inspectionRecipient(p):''}${(()=>{const due=data.inspections.filter(i=>i.property_id===p.id&&i.next_due).sort((a,b)=>a.next_due.localeCompare(b.next_due))[0];return due?`<div class="notice inspection-due ${isOverdue(due.next_due)?'overdue-item':''}"><strong>Next inspection: ${esc(fmtDay(due.next_due))}</strong> ${isStaff()?btn('Edit schedule','edit-inspection-schedule',due.id):''}</div>`:''})()}${isStaff()?`<div class="actions">${btn('Start inspection','new-inspection',p.id,true)}${offlineDownloadButton([p.id])}</div>`:''}${inspectionRows(data.inspections.filter(i=>i.property_id===p.id))}</div>`;
