 if(name==='assign-butler'){const p=data.properties.find(p=>p.id===key);return createForm('Select Residence Manager',select('userId','Administrator or staff','<option value="">Not assigned</option>'+option(data.users.filter(u=>u.active&&['admin','employee'].includes(u.role)),'id','name',p.account_manager_id)),'properties/manager',{propertyId:key});}
