document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;event.preventDefault();if(!data&&button.closest('.shell'))return;button.disabled=true;try{await action(button.dataset.action,button.dataset.id,button);}catch(error){toast(error.message);}finally{button.disabled=false;}});
document.addEventListener('change',async event=>{const el=event.target;if(!el.dataset.arrival)return;const a=data.arrivals.find(a=>a.id===el.dataset.arrival);try{const payload={id:a.id,version:a.version};if(el.dataset.item){const field=el.dataset.itemField;if(field==='substitutionNeeded')Object.assign(payload,{itemId:el.dataset.item,substitutionNeeded:el.checked,substitution:el.closest('.actions')?.querySelector('[data-item-field=\"substitution\"]')?.value||''});else if(field==='substitution')Object.assign(payload,{itemId:el.dataset.item,substitutionNeeded:el.closest('.actions')?.querySelector('[data-item-field=\"substitutionNeeded\"]')?.checked||false,substitution:el.value});else Object.assign(payload,{itemId:el.dataset.item,itemStatus:el.checked?'purchased':'requested'});}if(el.dataset.roomKey)Object.assign(payload,{roomKey:el.dataset.roomKey,roomReady:el.checked});await api('arrivals/update',payload);await load();toast(el.dataset.roomKey?'Room readiness saved.':el.dataset.itemField==='substitutionNeeded'||el.dataset.itemField==='substitution'?'Substitution details saved.':'Purchase status saved.');}catch(error){toast(error.message);await load();}});
// After signing out, draw the sign-in screen in place (login.js); never leave the old app on screen with data cleared.
function showSignIn(){document.body.classList.remove('signed-in','menu-open');try{history.replaceState(null,'','/login');}catch{}document.title='EstateAegis';$('modal')?.open&&$('modal').close();return boot();}
async function boot(){if(window.EA_SHELL_RECOVERING)return;try{await window.EAOffline?.ready;}catch{}try{const params=new URLSearchParams(location.search),workspaceToken=params.get('workspaceInvite');if(workspaceToken){await workspaceRegistration(workspaceToken);return;}const brandedSlug=location.pathname.match(/^\/client\/([a-z0-9-]+)$/i)?.[1];const invitation=params.get('invite');let brand=null;if(brandedSlug||invitation){const response=await fetch(brandedSlug?'/api/client-portal?slug='+encodeURIComponent(brandedSlug):'/api/invite-info?token='+encodeURIComponent(invitation));if(!response.ok){if(brandedSlug&&response.status>=500)throw Object.assign(Error('Client portal could not load.'),{status:response.status});if(invitation&&response.status>=500)throw Object.assign(Error('Invitation could not load.'),{status:response.status});authProblem(brandedSlug?'portal':'invite');return;}brand=await response.json();}const status=await api('status');if(status.user&&!invitation)await load();else portalAuth(status.configured,invitation,brand);}catch(error){if(typeof offlineBoot==='function'&&await offlineBoot(error))return;$('app').innerHTML=`<div class="loading" role="alert"><h1>EstateAegis couldn’t load</h1><p>${error.status?esc(error.message):'Check your internet connection.'}</p><p>Refresh the page to try again. If it keeps happening, email <a href="mailto:help@estateaegis.com">help@estateaegis.com</a>.</p></div>`;}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>boot());else boot();
function assetInspectionView(){const a=data.assets.find(a=>a.id===activeAssetInspection);if(!a)return empty('Asset unavailable.');const report=(activeAssetInspectionRecord?data.asset_inspections.find(i=>i.id===activeAssetInspectionRecord&&i.asset_id===a.id):null)||data.asset_inspections.filter(i=>i.asset_id===a.id).sort((x,y)=>y.inspection_date.localeCompare(x.inspection_date))[0];const items=['Exterior, hull or body condition','Tires, trailer or running gear','Engine, battery or power system','Fuel, oil, coolant or fluid levels','Safety equipment and required gear','Leaks, damage or warning indicators','Storage, cover and security'];if(assetInspectionReadOnly&&report)return head(`${a.name} inspection`,`${report.inspection_date} · Completed asset inspection`,btn('Back to assets','navigate','assets'))+`<div class="panel"><div class="actions"><a class="button primary" href="/api/asset-inspections/${report.id}/pdf">Download PDF</a></div>${report.answers.map(x=>`<div class="row"><div><strong>${esc(x.label)}</strong>${x.note?`<div class="muted">${esc(x.note)}</div>`:''}</div>${badge(x.status)}</div>`).join('')}<h3 class="summary">Overall notes</h3><p class="pre">${esc(report.notes||'No overall notes recorded.')}</p></div>`;return head(`${a.name} inspection`,`Record a focused inspection for this ${a.category||'asset'}.`,btn('Back to assets','navigate','assets'))+`<div class="panel asset-inspection-page"><p class="muted">Review each item that applies and record anything needing follow-up.</p><div class="field"><label for="asset-date">Inspection date</label><input id="asset-date" type="date" value="${today()}"></div>${items.map((label,i)=>`<div class="inspection-item"><div><strong>${esc(label)}</strong><div class="muted">Choose the result and add an observation if needed.</div></div><select id="asset-check-${i}"><option value="pass">Pass</option><option value="attention">Needs attention</option><option value="na">Not applicable</option></select><input id="asset-note-${i}" placeholder="Observation or follow-up note"></div>`).join('')}<div class="field full"><label for="asset-inspection-notes">Overall notes</label><textarea id="asset-inspection-notes" placeholder="Summarize the condition or work needed"></textarea></div><div class="actions">${btn('Save inspection','asset-inspection-save','',true)}</div></div>`;}
let routeAddressTimer,routeAddressRequest,routeAddressRevision=0;
document.addEventListener('input',event=>{
 const field=event.target;if(field.id!=='f-origin')return;
 const revision=++routeAddressRevision;clearTimeout(routeAddressTimer);routeAddressRequest?.abort();
 const results=$('routeOriginResults'),status=$('routeOriginStatus');if(!results)return;
 results.replaceChildren();status.textContent='';const q=field.value.trim();if(q.length<3)return;
 routeAddressTimer=setTimeout(async()=>{
  const controller=new AbortController();routeAddressRequest=controller;
  status.textContent='Finding addresses…';
  try{
   const response=await fetch('/api/geocode/autocomplete?q='+encodeURIComponent(q),{signal:controller.signal});
   if(!response.ok)throw Error('Lookup failed');
   const body=await response.json();if(revision!==routeAddressRevision||!field.isConnected)return;
   for(const feature of body.features||[]){
    const p=feature.properties||{};
    const address=[p.name,[p.housenumber,p.street].filter(Boolean).join(' '),p.city||p.town||p.village,p.state,p.postcode,p.country].filter(Boolean).join(', ');
    if(!address)continue;
    const button=document.createElement('button');button.type='button';button.className='address-suggestion';button.textContent=address;
    button.onclick=()=>{++routeAddressRevision;field.value=address;results.replaceChildren();status.textContent='Starting address selected.';field.focus();};
    results.appendChild(button);
   }
   status.textContent=results.children.length?'Select an address below.':'No matches. You can enter the address manually.';
  }catch(error){if(error.name!=='AbortError'&&revision===routeAddressRevision)status.textContent='Address search unavailable. Enter your address manually.';}
 },500);
});
document.addEventListener('click',async event=>{
 if(event.target.id!=='routeLocate')return;
 const button=event.target,field=$('f-origin'),status=$('routeOriginStatus');
 ++routeAddressRevision;clearTimeout(routeAddressTimer);routeAddressRequest?.abort();$('routeOriginResults').replaceChildren();
 if(!navigator.geolocation){status.textContent='Location is unavailable on this device. Enter an address manually.';return;}
 const revision=routeAddressRevision;button.disabled=true;status.textContent='Finding your location…';
 try{
  const position=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:15000,maximumAge:60000}));
  if(!field.isConnected||revision!==routeAddressRevision)return;
  const lat=position.coords.latitude,lon=position.coords.longitude;
  try{const response=await fetch(`/api/geocode/reverse?lat=${lat}&lon=${lon}`,{signal:AbortSignal.timeout(8000)});const body=await response.json();const p=body.features?.[0]?.properties||{};const address=p.formatted||[p.name,[p.housenumber,p.street].filter(Boolean).join(' '),p.city||p.town||p.village,p.state,p.postcode,p.country].filter(Boolean).join(', ');field.value=address||`${lat.toFixed(6)},${lon.toFixed(6)}`;status.textContent=address?'Current address found.':'Current location selected.';}catch{field.value=`${lat.toFixed(6)},${lon.toFixed(6)}`;status.textContent='Location selected. Coordinates will be used as your starting point.';}
 }catch(error){if(field.isConnected&&revision===routeAddressRevision)status.textContent=error.code===1?'Location permission denied. Allow location access or enter an address manually.':'Could not find your location. Try again or enter an address manually.';}
 finally{button.disabled=false;}
});
function globalSearch(){const q=search.trim().toLowerCase();if(!q)return view();const match=v=>Object.values(v||{}).some(x=>typeof x==='string'&&x.toLowerCase().includes(q));const props=data.properties.filter(match),jobs=data.work.filter(match);return head('Search results',`Matches for “${esc(search)}”`)+`<div class="panel"><h2>Residences</h2>${props.map(p=>`<div class="row"><strong>${esc(p.name)}</strong>${btn('View residence','property',p.id)}</div>`).join('')||empty('No matching residences.')}</div><div class="panel"><h2>Work orders</h2>${workRows(jobs)||empty('No matching work orders.')}</div>`;}
window.addEventListener('focus',()=>{if(data&&page!=='inspection'&&!$('modal').open&&Date.now()-lastLoadAt>1500)load().catch(error=>toast(error.message));});
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 Promise.resolve(document.modelContext.registerTool({name:'open_estateos_inspection',title:'Open inspection report',description:'Open an inspection already accessible to the signed-in account. Does not publish or modify records.',inputSchema:{type:'object',properties:{inspectionId:{type:'string'}},required:['inspectionId'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},async execute(input){if(!input||typeof input.inspectionId!=='string'||Object.keys(input).length!==1)throw Error('Provide an inspectionId.');await load();const report=data.inspections.find(i=>i.id===input.inspectionId);if(!report)throw Error('Inspection unavailable to this account.');activeInspection=report.id;page='inspection';render();return {id:report.id,status:report.status};}},{signal:lifecycle.signal})).catch(()=>{});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}


