/* Session timeout and refresh-safe SPA state */
(()=>{
 const idleLimit=30*60*1000, stateKey='estateos:last-view', activityKey='estateos:last-activity';
 const saveView=()=>{if(!data?.user)return;try{localStorage.setItem(stateKey,JSON.stringify({userId:data.user.id,route:window.EARoute?.current?.()||'',page,propertyId,tab,activeInspection,at:Date.now()}));localStorage.setItem(activityKey,String(Date.now()));}catch{}};
 if(!page)page='dashboard';
 const originalLoad=load;load=async function(...args){if(!data){page='dashboard';propertyId=null;tab='overview';activeInspection=null;activeAssetInspection=null;activeAssetInspectionRecord=null;assetInspectionReadOnly=false;activeArrival=null;activeClient=null;}return originalLoad(...args);};
 const markActivity=()=>{if(data)try{localStorage.setItem(activityKey,String(Date.now()));}catch{}};
 ['pointerdown','keydown','touchstart','mousemove','scroll'].forEach(type=>window.addEventListener(type,markActivity,{passive:true}));
 setInterval(()=>{
   if(data){saveView();const last=Number(localStorage.getItem(activityKey)||Date.now());if(Date.now()-last>=idleLimit&&!(window.EAOffline?.holdSession?.())){localStorage.removeItem(stateKey);localStorage.removeItem(activityKey);fetch('/api/logout',{method:'POST',credentials:'same-origin',keepalive:true}).catch(()=>{}).finally(()=>location.replace('/login'));}}
 },1000);
 window.addEventListener('beforeunload',saveView);

})();

/* Family access: show the primary client and allow admins to suspend access. */
(()=>{
 familyMemberActions=function(p,m){
  if(data.user.role!=='admin')return '';
  const email=String(m.email||'').trim().toLowerCase();
  const account=(data.users||[]).find(u=>u.role==='client'&&u.client_id===p.client_id&&(((m.accessUserIds||[]).includes(u.id))||(email&&String(u.email||'').toLowerCase()===email)));
  const pending=(data.invitations||[]).filter(i=>i.clientId===p.client_id&&i.role==='client'&&i.status==='pending'&&(((m.invitationIds||[]).includes(i.id))||(email&&String(i.email||'').toLowerCase()===email)));
  const action=(text,name,id)=>'<button data-action="'+name+'" data-id="'+esc(id||m.id)+'" data-property-id="'+esc(p.id)+'">'+text+'</button>';
  return '<div class="family-member-actions"><div class="muted">'+(account?(account.active?'Client access active':'Client access suspended'):pending.length?'Invitation pending':email?'Not invited':'Add an email to invite')+'</div><div class="actions">'+action(email?'Edit email':'Add email','family-member-email')+(!account&&!pending.length&&email?action('Send invite','family-send-invite'):'')+(account?(account.active?action('Suspend access','suspend-user',account.id):action('Reactivate access','reactivate-user',account.id)):'')+pending.map(i=>btn('Cancel invitation','cancel-invite',i.id)).join('')+action('Remove','residence-member-delete')+'</div></div>';
 };
 clientView=function(c){
  const homes=data.properties.filter(p=>p.client_id===c.id);
  const primary=(data.users||[]).find(u=>u.role==='client'&&u.client_id===c.id);
  const primaryName=primary?.name||c.name||'Primary client';
  const primaryEmail=primary?.email||c.email||'No email';
  const primaryActions=primary?(primary.active?btn('Suspend access','suspend-user',primary.id):btn('Reactivate access','reactivate-user',primary.id)):'';
  return head(c.name||'Family','Family details',btn('Back to families','navigate','clients'))+'<div class="panel"><h2>'+esc(c.name||'Family')+'</h2><p class="muted">'+esc(c.email||'No email')+(c.phone?' · '+esc(c.phone):'')+'</p><h3>Primary client</h3><div class="row"><div><strong>'+esc(primaryName)+'</strong><div class="muted">'+esc(primaryEmail)+' · Main client</div></div><div class="actions">'+primaryActions+'</div></div><h3>Residences</h3>'+homes.map(p=>'<div class="row"><div><strong>'+esc(p.name)+'</strong><div class="muted">'+esc(p.address||'Address not entered')+'</div></div>'+btn('View residence','property',p.id)+'</div>').join('')+'</div>';
 };
})();
/* Keep invitation form enhancement idempotent. */
(()=>{const d=Object.getOwnPropertyDescriptor(Node.prototype,'textContent');if(d?.set&&!window.__estateTextContentGuard){window.__estateTextContentGuard=true;Object.defineProperty(Node.prototype,'textContent',{configurable:d.configurable,enumerable:d.enumerable,get:d.get,set(value){if(this.textContent===value)return;d.set.call(this,value);}});}})();
(()=>{const update=()=>{const clientView=location.pathname==='/client-login'||location.search.includes('invite=')||document.querySelector('.resident-sidebar');document.documentElement.classList.toggle('client-view',Boolean(clientView));};new MutationObserver(update).observe(document.body,{childList:true,subtree:true});update();})();

